#include <iostream>
#include <string>
using namespace std;

class ATMLight {
private:
    long long balance;
public:
    void init(long long b) {
        balance = b;
    }
    void deposit(long long amt) {
        balance = balance + amt;
        cout << "Deposit " << amt << ", balance " << balance << endl;
    }
    void withdraw(long long amt) {
        if (amt > balance) {
            cout << "Withdraw " << amt << " declined, balance " << balance << endl;
        } else {
            balance = balance - amt;
            cout << "Withdraw " << amt << ", balance " << balance << endl;
        }
    }
    void printReceipt() {
        cout << "Final balance: " << balance << endl;
    }
};

int main() {
    ATMLight atm;
    long long start;
    int n;
    cin >> start >> n;
    atm.init(start);
    for (int i = 0; i < n; i++) {
        string cmd;
        long long amt;
        cin >> cmd >> amt;
        if (cmd == "D") {
            atm.deposit(amt);
        } else {
            atm.withdraw(amt);
        }
    }
    atm.printReceipt();
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int n;
    long long balance;
    cin >> n >> balance;
    int processed = 0;
    int record = 1;
    do {
        long long amount;
        cin >> amount;
        if (amount == -1) {
            cout << "Cancelled at record " << record << endl;
            break;
        }
        if (amount <= balance) {
            balance -= amount;
            cout << "TXN " << record << ": Approved, balance " << balance << endl;
        } else {
            cout << "TXN " << record << ": Declined" << endl;
        }
        processed++;
        record++;
    } while (record <= n);
    cout << "Processed: " << processed << endl;
    cout << "Final balance: " << balance << endl;
    return 0;
}

#include <iostream>
using namespace std;

class Employee {
public:
    virtual int salary() = 0;   // pure virtual
    virtual ~Employee() {}
};

class Manager : public Employee {
    int base, bonus;
public:
    Manager(int b, int bo) : base(b), bonus(bo) {}
    int salary() { return base + bonus; }
};

class Worker : public Employee {
    int rate, hours;
public:
    Worker(int r, int h) : rate(r), hours(h) {}
    int salary() { return rate * hours; }
};

int main() {
    char code;
    cin >> code;
    Employee* e = nullptr;
    if (code == 'M') {
        int base, bonus;
        cin >> base >> bonus;
        e = new Manager(base, bonus);
    } else {
        int rate, hours;
        cin >> rate >> hours;
        e = new Worker(rate, hours);
    }
    cout << "Salary: " << e->salary() << endl;
    delete e;
    return 0;
}

#include <iostream>
using namespace std;

class Machine {
public:
    void ready() { cout << "Machine ready" << endl; }   // concrete method
    virtual void work() = 0;                            // pure virtual
    virtual ~Machine() {}
};

class Printer : public Machine {
public:
    void work() { cout << "Printing job on unit " << unit << endl; }
    Printer(int u) : unit(u) {}
private:
    int unit;
};

class Scanner : public Machine {
public:
    void work() { cout << "Scanning page on unit " << unit << endl; }
    Scanner(int u) : unit(u) {}
private:
    int unit;
};

int main() {
    char code;
    int unit;
    cin >> code >> unit;
    Machine* m = nullptr;
    if (code == 'P') m = new Printer(unit);
    else m = new Scanner(unit);
    m->ready();   // concrete method from the abstract base
    m->work();    // derived implementation
    delete m;
    return 0;
}

