#include <iostream>
#include <string>
using namespace std;

int main() {
    string a, b;
    cin >> a >> b;
    int ca[26] = {0};
    int cb[26] = {0};
    for (int i = 0; i < (int)a.length(); i++) {
        char c = a[i];
        if (c >= 'A' && c <= 'Z') {
            c = c - 'A' + 'a';
        }
        ca[c - 'a']++;
    }
    for (int i = 0; i < (int)b.length(); i++) {
        char c = b[i];
        if (c >= 'A' && c <= 'Z') {
            c = c - 'A' + 'a';
        }
        cb[c - 'a']++;
    }
    bool same = true;
    for (int i = 0; i < 26; i++) {
        if (ca[i] != cb[i]) {
            same = false;
        }
    }
    if (same) {
        cout << "Anagrams" << endl;
    } else {
        cout << "Not anagrams" << endl;
    }
    return 0;
}

