int main() {
    string word;
    int k;
    cin >> word >> k;

    string cipher = "";
    for (int i = 0; i < (int)word.length(); i++) {
        char c = word[i];
        if (c >= 'a' && c <= 'z') {
            c = (char)('a' + (c - 'a' + k) % 26);
        } else if (c >= 'A' && c <= 'Z') {
            c = (char)('A' + (c - 'A' + k) % 26);
        }
        cipher += c;
    }

    // reverse the cipher text by hand
    string back = "";
