#include <iostream>
#include <iomanip>
using namespace std;

class Date {
public:
    int d, m, y;
    Date(int dd = 1, int mm = 1, int yy = 2000) : d(dd), m(mm), y(yy) {}
    static bool isLeap(int year) {
        return (year % 400 == 0) || (year % 4 == 0 && year % 100 != 0);
    }
    static int monthDays(int month, int year) {
        if (month == 2) return isLeap(year) ? 29 : 28;
        if (month == 4 || month == 6 || month == 9 || month == 11) return 30;
        return 31;
    }
    void advance() {
        d++;
        if (d > monthDays(m, y)) {
            d = 1;
            m++;
            if (m > 12) {
                m = 1;
                y++;
            }
        }
    }
    Date& operator++() {
        advance();
        return *this;
    }
    Date operator++(int) {
        Date temp = *this;
        advance();
        return temp;
    }
    void print() const {
        cout << setw(2) << setfill('0') << d << "-"
             << setw(2) << m << "-" << y << endl;
    }
};

int main() {
    int d, m, y, n;
    cin >> d >> m >> y >> n;
    Date cur(d, m, y);
    cur.print();
    for (int k = 1; k <= n; k++) {
        if (k % 2 == 1)
            ++cur;
        else
            cur++;
        cur.print();
    }
    return 0;
}

