        int r, i;
        cin >> r >> i;
        sum += Complex(r, i);
    }
    cin >> r2 >> i2;
    Complex expected(r2, i2);
    cout << "Sum: ";
    sum.show();
    cout << endl;
    if (sum == expected)
        cout << "Equal" << endl;
    else
        cout << "Not equal" << endl;
    return 0;
}

