class Buffer {
    int size;
    int *data;
public:
    Buffer(int n) {
        size = n;
        data = new int[size];
        for (int i = 0; i < size; i++) {
            data[i] = i + 1;
        }
        cout << "Buffer created with " << size << " slots" << endl;
    }
    Buffer(const Buffer &other) {
        size = other.size;
        data = new int[size];
        for (int i = 0; i < size; i++) {
            data[i] = other.data[i];
        }
        cout << "Deep copy of " << size << " slots performed" << endl;
    }
    ~Buffer() {
        delete[] data;
        cout << "Buffer freed" << endl;
    }
    void set(int idx, int val) {
        data[idx] = val;
    }
    void print(const char *label) {
        cout << label << ":";
        for (int i = 0; i < size; i++) {
            cout << " " << data[i];
        }
        cout << endl;
    }
};

int main() {
    int n;
    cin >> n;
    Buffer a(n);
    Buffer b = a;
    a.print("Original");
    b.print("Copy");
    b.set(0, 100);
    b.print("Copy after edit");
    a.print("Original after edit");
    return 0;
}

