    char op;
    cin >> m1 >> c1 >> m2 >> c2 >> op;
    Distance a(m1, c1), b(m2, c2);
    Distance r;
    if (op == '+')
        r = a + b;
    else
        r = a - b;
    cout << "Result: " << r.metres << " m " << r.cm << " cm" << endl;
    return 0;
}

