#include <iostream>
#include <iomanip>
using namespace std;

int main() {
    int scores[2000];
    int count = 0;
    long long sum = 0;
    int s;
    cin >> s;
    while (s != -1) {
        scores[count] = s;
        count++;
        sum += s;
        cin >> s;
    }
    int highest = scores[0];
    int lowest = scores[0];
    for (int i = 1; i < count; i++) {
        if (scores[i] > highest) {
            highest = scores[i];
        }
        if (scores[i] < lowest) {
            lowest = scores[i];
        }
    }
    double average = (double)sum / count;
    int above = 0;
    for (int i = 0; i < count; i++) {
        if (scores[i] > average) {
            above++;
        }
    }
    cout << "Players: " << count << endl;
    cout << "Highest: " << highest << endl;
    cout << "Lowest: " << lowest << endl;
    cout << fixed << setprecision(2) << "Average: " << average << endl;
    cout << "Above average: " << above << endl;
    return 0;
}

