#include <iostream>
#include <iomanip>
#include <string>
using namespace std;

void readExpense(string& label, double& amount) {
    cin >> label >> amount;
}

double totalOf(double a, double b) {
    return a + b;
}

void swapByRef(double& x, double& y) {
    double temp = x;
    x = y;
    y = temp;
}

void swapByPtr(double* x, double* y) {
    double temp = *x;
    *x = *y;
    *y = temp;
}

int main() {
    string label1, label2;
    double amount1, amount2;
    readExpense(label1, amount1);
    readExpense(label2, amount2);
    cout << "=== EXPENSE REPORT ===" << endl;
    cout << fixed << setprecision(2);
    cout << label1 << ": " << amount1 << endl;
    cout << label2 << ": " << amount2 << endl;
    cout << "Total: " << totalOf(amount1, amount2) << endl;
    swapByRef(amount1, amount2);
    cout << "After reference swap:" << endl;
    cout << label1 << ": " << amount1 << endl;
    cout << label2 << ": " << amount2 << endl;
    swapByPtr(&amount1, &amount2);
    cout << "After pointer swap:" << endl;
    cout << label1 << ": " << amount1 << endl;
    cout << label2 << ": " << amount2 << endl;
    return 0;
}

#include <iostream>
using namespace std;

class Bill {
public:
    virtual ~Bill() {}
    virtual void print(int amount) {
        cout << "Base amount: " << amount << endl;
    }
};

class TaxedBill : public Bill {
public:
    void print(int amount) {
        Bill::print(amount);              // reuse the base behaviour
        int tax = amount / 10;
        cout << "Tax added: " << tax << endl;
        cout << "Final total: " << amount + tax << endl;
    }
};

int main() {
    int amount;
    cin >> amount;
    TaxedBill t;
    Bill* b = &t;
    b->print(amount);   // virtual dispatch reaches the extended override
    return 0;
}

