#include <iostream>
using namespace std;

int gcd(int a, int b) {
    while (b != 0) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

class Fraction {
public:
    int num, den;
    Fraction(int n = 0, int d = 1) : num(n), den(d) {}
    Fraction operator+(const Fraction& o) const {
        return Fraction(num * o.den + o.num * den, den * o.den);
    }
    void reduce() {
        int g = gcd(num < 0 ? -num : num, den);
        num /= g;
        den /= g;
    }
    friend istream& operator>>(istream& in, Fraction& f) {
        in >> f.num >> f.den;
        return in;
    }
    friend ostream& operator<<(ostream& out, const Fraction& f) {
        out << f.num << "/" << f.den;
        return out;
    }
};

int main() {
    Fraction f1, f2;
    cin >> f1 >> f2;
    Fraction sum = f1 + f2;
    f1.reduce();
    f2.reduce();
    sum.reduce();
    cout << "First: " << f1 << endl;
    cout << "Second: " << f2 << endl;
    cout << "Sum: " << sum << endl;
    return 0;
}

