#include <iostream>
#include <iomanip>
using namespace std;

class Gradebook {
private:
    int marks[3];
public:
    void setMark(int index, int m) {
        marks[index] = m;
    }
    int getMark(int index) {
        return marks[index];
    }
    double getAverage() {
        return (marks[0] + marks[1] + marks[2]) / 3.0;
    }
    int getHighest() {
        int best = marks[0];
        if (marks[1] > best) {
            best = marks[1];
        }
        if (marks[2] > best) {
            best = marks[2];
        }
        return best;
    }
    bool isPass() {
        return getAverage() >= 40.0;
    }
};

int main() {
    Gradebook g;
    int m1, m2, m3;
    cin >> m1 >> m2 >> m3;
    g.setMark(0, m1);
    g.setMark(1, m2);
    g.setMark(2, m3);
    cout << "Marks: " << g.getMark(0) << " " << g.getMark(1) << " " << g.getMark(2) << endl;
    cout << fixed << setprecision(2) << "Average: " << g.getAverage() << endl;
    cout << "Highest: " << g.getHighest() << endl;
    cout << "Result: " << (g.isPass() ? "Pass" : "Fail") << endl;
    return 0;
}

