#include <iostream>
#include <string>
using namespace std;

class DiscountPolicy {
public:
    virtual ~DiscountPolicy() {}
    virtual int apply(int amount) { return amount; }
    virtual string name() { return "NoDiscount"; }
};

class NoDiscount : public DiscountPolicy {
public:
    int apply(int amount) { return amount; }
    string name() { return "NoDiscount"; }
};

class BulkDiscount : public DiscountPolicy {
public:
    int apply(int amount) { return amount - amount / 10; }   // 10% off in whole rupees
    string name() { return "BulkDiscount"; }
};

class LoyaltyDiscount : public DiscountPolicy {
public:
    int apply(int amount) { return amount - 50; }            // flat 50 off
    string name() { return "LoyaltyDiscount"; }
};

int main() {
    int n;
    cin >> n;
    DiscountPolicy* policies[3];
    policies[0] = new NoDiscount();
    policies[1] = new BulkDiscount();
    policies[2] = new LoyaltyDiscount();
    int totalOriginal = 0, totalPayable = 0;
    for (int i = 1; i <= n; i++) {
        char code;
        int price;
        cin >> code >> price;
        int idx = 0;
        if (code == 'B') idx = 1;
        else if (code == 'L') idx = 2;
        int payable = policies[idx]->apply(price);   // polymorphic discount
        cout << "Item " << i << " (" << policies[idx]->name() << "): "
             << price << " -> " << payable << endl;
        totalOriginal += price;
        totalPayable += payable;
    }
    cout << "Original total: " << totalOriginal << endl;
    cout << "Payable total: " << totalPayable << endl;
    cout << "Saved: " << totalOriginal - totalPayable << endl;
    for (int i = 0; i < 3; i++) delete policies[i];
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

// recursion takes one digit from each code per step, then appends the leftovers
string mergeCodes(const string &first, const string &second, int i) {
    if (i >= (int)first.size() && i >= (int)second.size()) {
        return "";
    }
    string merged = "";
    if (i < (int)first.size()) {
        merged += first[i];
    }
    if (i < (int)second.size()) {
        merged += second[i];
    }
    return merged + mergeCodes(first, second, i + 1);
}

// recursion walks the merged code and adds digit values
int digitSum(const string &text, int i) {
    if (i == (int)text.size()) {
        return 0;
    }
    return (text[i] - '0') + digitSum(text, i + 1);
}

int main() {
    long long a, b;
    cin >> a >> b;
    string first = to_string(a);
    string second = to_string(b);
    string merged = mergeCodes(first, second, 0);
    cout << "Code A: " << first << endl;
    cout << "Code B: " << second << endl;
    cout << "Merged code: " << merged << endl;
    cout << "Merged length: " << merged.size() << endl;
    cout << "Merged digit sum: " << digitSum(merged, 0) << endl;
    return 0;
}

