#include <iostream>
#include <vector>
#include <iomanip>
using namespace std;

template <class T>
class Stats {
    vector<T> data;
public:
    void add(T v) {
        data.push_back(v);
    }
    T getMin() {
        T m = data[0];
        for (int i = 1; i < (int)data.size(); i++) {
            if (data[i] < m) m = data[i];
        }
        return m;
    }
    T getMax() {
        T m = data[0];
        for (int i = 1; i < (int)data.size(); i++) {
            if (data[i] > m) m = data[i];
        }
        return m;
    }
    double getMean() {
        double sum = 0;
        for (int i = 0; i < (int)data.size(); i++) {
            sum += data[i];
        }
        return sum / data.size();
    }
};

int main() {
    int n;
    cin >> n;
    Stats<int> si;
    Stats<double> sd;
    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        si.add(x);
    }
    for (int i = 0; i < n; i++) {
        double x;
        cin >> x;
        sd.add(x);
    }
    cout << "Int stats:" << endl;
    cout << "Min: " << si.getMin() << endl;
    cout << "Max: " << si.getMax() << endl;
    cout << fixed << setprecision(2);
    cout << "Mean: " << si.getMean() << endl;
    cout << "Double stats:" << endl;
    cout << "Min: " << sd.getMin() << endl;
    cout << "Max: " << sd.getMax() << endl;
    cout << "Mean: " << sd.getMean() << endl;
    return 0;
}

