#include <iostream>
#include <string>
using namespace std;

class LibraryMember {
private:
    string name;
    int borrowed;
public:
    void setName(string n) {
        name = n;
    }
    void reset() {
        borrowed = 0;
    }
    bool borrowBook() {
        if (borrowed >= 5) {
            return false;
        }
        borrowed = borrowed + 1;
        return true;
    }
    bool returnBook() {
        if (borrowed <= 0) {
            return false;
        }
        borrowed = borrowed - 1;
        return true;
    }
    int getBorrowed() {
        return borrowed;
    }
    string getName() {
        return name;
    }
};

int main() {
    LibraryMember m;
    string name;
    cin >> name;
    m.setName(name);
    m.reset();
    cout << "Member: " << m.getName() << endl;
    for (int i = 0; i < 5; i++) {
        char cmd;
        cin >> cmd;
        if (cmd == 'B') {
            if (m.borrowBook()) {
                cout << "Borrow OK, now " << m.getBorrowed() << endl;
            } else {
                cout << "Borrow denied, now " << m.getBorrowed() << endl;
            }
        } else {
            if (m.returnBook()) {
                cout << "Return OK, now " << m.getBorrowed() << endl;
            } else {
                cout << "Return denied, now " << m.getBorrowed() << endl;
            }
        }
    }
