#include <iostream>
#include <string>
using namespace std;

int main() {
    string plate;
    cin >> plate;
    int n = plate.length();

    bool allowed = true;
    bool hasDigit = false;
    bool hasLetter = false;
    int digitSum = 0;
    for (int i = 0; i < n; i++) {
        char c = plate[i];
        bool letter = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
        bool digit = (c >= '0' && c <= '9');
        if (!letter && !digit) {
            allowed = false;
        }
        if (digit) {
            hasDigit = true;
            digitSum += c - '0';
        }
        if (letter) {
            hasLetter = true;
        }
    }

    string r1 = "FAIL", r2 = "FAIL", r3 = "FAIL", r4 = "FAIL", r5 = "FAIL";
    if (n >= 6 && n <= 10) {
        r1 = "PASS";
    }
    if (allowed) {
        r2 = "PASS";
    }
    if (hasDigit) {
        r3 = "PASS";
    }
    if (hasLetter) {
        r4 = "PASS";
    }
    if (digitSum % 7 == 0) {
        r5 = "PASS";
    }

    cout << "Rule 1 (length 6-10): " << r1 << endl;
    cout << "Rule 2 (letters and digits only): " << r2 << endl;
    cout << "Rule 3 (has a digit): " << r3 << endl;
    cout << "Rule 4 (has a letter): " << r4 << endl;
    cout << "Rule 5 (digit sum divisible by 7): " << r5 << endl;
    if (r1 == "PASS" && r2 == "PASS" && r3 == "PASS" && r4 == "PASS" && r5 == "PASS") {
        cout << "Verdict: VALID" << endl;
    } else {
        cout << "Verdict: INVALID" << endl;
    }
    return 0;
}

