#include <iostream>
#include <string>
using namespace std;

// recursion compares the outer pair and moves both ends inward
bool isPalindrome(const string &text, int left, int right) {
    if (left >= right) {
        return true;
    }
    if (text[left] != text[right]) {
        return false;
    }
    return isPalindrome(text, left + 1, right - 1);
}

int main() {
    string plate;
    cin >> plate;
    if (isPalindrome(plate, 0, (int)plate.size() - 1)) {
        cout << "Palindrome: Yes" << endl;
    } else {
        cout << "Palindrome: No" << endl;
    }
    return 0;
}

#include <iostream>
#include <thread>
#include <vector>
using namespace std;

vector<int> values;
long long partialSum[2];

void sumRange(int slot, int lo, int hi) {
    long long s = 0;
    for (int i = lo; i < hi; i++) {
        s += values[i];
    }
    partialSum[slot] = s;
}

int main() {
    int n;
    cin >> n;
    values.resize(n);
    for (int i = 0; i < n; i++) {
        cin >> values[i];
    }
    int mid = n / 2;
    thread first(sumRange, 0, 0, mid);
    thread second(sumRange, 1, mid, n);
    first.join();
    second.join();
    cout << "First half: " << partialSum[0] << endl;
    cout << "Second half: " << partialSum[1] << endl;
    cout << "Total: " << partialSum[0] + partialSum[1] << endl;
    return 0;
}

