#include <iostream>
#include <string>
using namespace std;

class Slot {
private:
    bool occupied;
    string car;
public:
    void init() {
        occupied = false;
        car = "";
    }
    bool park(string name) {
        if (occupied) {
            return false;
        }
        car = name;
        occupied = true;
        return true;
    }
    bool leave() {
        if (!occupied) {
            return false;
        }
        car = "";
        occupied = false;
        return true;
    }
    string status() {
        if (occupied) {
            return car;
        }
        return "empty";
    }
};

int main() {
    Slot slots[10];
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < 10; i++) {
        slots[i].init();
    }
    for (int i = 0; i < m; i++) {
        string cmd;
        cin >> cmd;
        if (cmd == "E") {
            int s;
            string car;
            cin >> s >> car;
            if (slots[s - 1].park(car)) {
                cout << "Car " << car << " parked in slot " << s << endl;
            } else {
                cout << "Slot " << s << " is occupied" << endl;
            }
        } else if (cmd == "L") {
            int s;
            cin >> s;
            if (slots[s - 1].leave()) {
                cout << "Slot " << s << " is free now" << endl;
            } else {
                cout << "Slot " << s << " is already empty" << endl;
            }
        } else {
            for (int k = 0; k < n; k++) {
                cout << "Slot " << (k + 1) << ": " << slots[k].status() << endl;
            }
        }
    }
    return 0;
}

