double grossSalary(double basic, double bonusPercent = 10) {
    return basic + basic * bonusPercent / 100.0;
}

double totalDeductions(double gross) {
    return gross * 0.12;
}

double netSalary(double gross, double deductions) {
    return gross - deductions;
}

void printSlip(string name, double net) {
    cout << "Employee: " << name << endl;
    cout << "Net pay: " << net << endl;
}

void printSlip(string name, double net, double bonusAmount) {
    cout << "Employee: " << name << endl;
    cout << "Bonus: " << bonusAmount << endl;
    cout << "Net pay: " << net << endl;
}

int main() {
    string name1, name2;
    double basic1, basic2;
    int bonus2;
    cin >> name1 >> basic1 >> name2 >> basic2 >> bonus2;
    double gross1 = grossSalary(basic1);
    double net1 = netSalary(gross1, totalDeductions(gross1));
    double gross2 = grossSalary(basic2, bonus2);
    double net2 = netSalary(gross2, totalDeductions(gross2));
    cout << fixed << setprecision(2);
    printSlip(name1, net1);
    printSlip(name2, net2, basic2 * bonus2 / 100.0);
    return 0;
}

#include <iostream>
#include <iomanip>
#include <string>
using namespace std;

int main() {
    int dayCode, hours;
    char grade;
    cin >> dayCode >> hours >> grade;
    if (dayCode < 1 || dayCode > 3) {
        cout << "Invalid day code" << endl;
        return 0;
    }
    if (grade != 'A' && grade != 'B' && grade != 'C') {
        cout << "Invalid grade" << endl;
        return 0;
    }
    string dayName;
    double mult;
    if (dayCode == 1) {
        dayName = "Weekday";
        mult = 1.0;
    } else if (dayCode == 2) {
        dayName = "Weekend";
        mult = 1.5;
    } else {
        dayName = "Holiday";
        mult = 2.0;
    }
    double baseRate;
    if (grade == 'A') {
        baseRate = 300;
    } else if (grade == 'B') {
        baseRate = 250;
    } else {
        baseRate = 200;
    }
    int ot = 0;
    if (hours > 8) {
        ot = hours - 8;
    }
    if (dayCode == 3 && hours > 0 && ot < 4) {
        ot = 4;
    }
    double rate = baseRate * mult;
    double pay = ot * rate;
    cout << "Day type: " << dayName << endl;
    cout << "Hours worked: " << hours << endl;
    cout << "Overtime hours: " << ot << endl;
    cout << fixed << setprecision(2);
    cout << "Rate per hour: " << rate << endl;
    cout << "Overtime pay: " << pay << endl;
    return 0;
}

