#include <iostream>
using namespace std;

class Polynomial {
public:
    int deg;
    int coeff[11];
    Polynomial(int d = 0) : deg(d) {
        for (int i = 0; i <= 10; i++) coeff[i] = 0;
    }
    Polynomial operator+(const Polynomial& o) const {
        int md = deg > o.deg ? deg : o.deg;
        Polynomial r(md);
        for (int i = 0; i <= md; i++) {
            int a = (i <= deg) ? coeff[i] : 0;
            int b = (i <= o.deg) ? o.coeff[i] : 0;
            r.coeff[i] = a + b;
        }
        return r;
    }
    Polynomial operator*(int s) const {
        Polynomial r(deg);
        for (int i = 0; i <= deg; i++) r.coeff[i] = coeff[i] * s;
        return r;
    }
    void print() const {
        bool first = true;
        for (int k = deg; k >= 0; k--) {
            int c = coeff[k];
            if (c == 0) continue;
            if (!first)
                cout << (c > 0 ? " + " : " - ");
            else if (c < 0)
                cout << "-";
            int a = c < 0 ? -c : c;
            if (k == 0) {
                cout << a;
            } else {
                if (a != 1) cout << a;
                cout << "x";
                if (k > 1) cout << "^" << k;
            }
            first = false;
        }
        if (first) cout << "0";
        cout << endl;
    }
};

int main() {
    int degA;
    cin >> degA;
    Polynomial A(degA);
    for (int i = 0; i <= degA; i++) cin >> A.coeff[i];
    int degB;
    cin >> degB;
    Polynomial B(degB);
    for (int i = 0; i <= degB; i++) cin >> B.coeff[i];
    int s;
    cin >> s;
    Polynomial sum = A + B;
    Polynomial scaled = A * s;
    cout << "Sum: ";
    sum.print();
    cout << "Scaled: ";
    scaled.print();
    return 0;
}

