#include <iostream>
#include <string>
using namespace std;

class IntStack {
    int *data;
    int cap;
    int top;
public:
    IntStack(int c) {
        cap = c;
        top = 0;
        data = new int[cap];
        cout << "Stack allocated with capacity " << cap << endl;
    }
    ~IntStack() {
        delete[] data;
        cout << "Stack memory released" << endl;
    }
    void push(int v) {
        if (top == cap) {
            cout << "Stack overflow" << endl;
            return;
        }
        data[top] = v;
        top++;
        cout << "Pushed " << v << endl;
    }
    void pop() {
        if (top == 0) {
            cout << "Stack underflow" << endl;
            return;
        }
        top--;
        cout << "Popped " << data[top] << endl;
    }
};

int main() {
    int cap, k;
    cin >> cap >> k;
    IntStack s(cap);
    for (int i = 0; i < k; i++) {
        string op;
        cin >> op;
        if (op == "push") {
            int v;
            cin >> v;
            s.push(v);
        } else {
            s.pop();
        }
    }
    return 0;
}

