};

class HtmlRenderer : public ReportRenderer {
public:
    HtmlRenderer(string t) : ReportRenderer(t) {}
    void header() { cout << "<h1>" << title << "</h1>" << endl; }
    void body() { cout << "<p>report body</p>" << endl; }
    void footer() { cout << "<small>generated by atom</small>" << endl; }
};

