#include <iostream>
using namespace std;

class Sensor {
private:
    int low;
    int high;
    int value;
public:
    void setRange(int lo, int hi) {
        low = lo;
        high = hi;
    }
    void setReading(int r) {
        if (r < low) {
            value = low;
        } else if (r > high) {
            value = high;
        } else {
            value = r;
        }
    }
    int getReading() {
        return value;
    }
};

int main() {
    Sensor s;
    int lo, hi, r1, r2, r3;
    cin >> lo >> hi >> r1 >> r2 >> r3;
    s.setRange(lo, hi);
    s.setReading(r1);
    cout << "Reading 1: " << s.getReading() << endl;
    s.setReading(r2);
    cout << "Reading 2: " << s.getReading() << endl;
    s.setReading(r3);
    cout << "Reading 3: " << s.getReading() << endl;
    return 0;
}

