#include <iostream>
#include <string>
using namespace std;

int main() {
    int c;
    cin >> c;
    int* st = new int[c];
    int* top = st;
    int total = c;
    while (total > 0) {
        total--;
        string cmd;
        cin >> cmd;
        if (cmd == "push") {
            int x;
            cin >> x;
            *top = x;
            top++;
        } else if (cmd == "pop") {
            if (top == st) {
                cout << "UNDERFLOW" << endl;
            } else {
                top--;
                cout << *top << endl;
            }
        } else if (cmd == "peek") {
            if (top == st) {
                cout << "UNDERFLOW" << endl;
            } else {
                cout << *(top - 1) << endl;
            }
        }
    }
    cout << "Stack from top: ";
    int remaining = top - st;
    if (remaining == 0) {
        cout << "EMPTY";
    } else {
        for (int i = remaining - 1; i >= 0; i--) {
            cout << *(st + i);
            if (i > 0) {
                cout << " ";
            }
        }
    }
    cout << endl;
    delete[] st;
    return 0;
}

