#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;
    int price[1000];
    for (int i = 0; i < n; i++) {
        cin >> price[i];
    }
    int bestProfit = 0;
    int buyDay = -1;
    int sellDay = -1;
    int minPrice = price[0];
    int minDay = 0;
    for (int j = 1; j < n; j++) {
        int profit = price[j] - minPrice;
        if (profit > bestProfit) {
            bestProfit = profit;
            buyDay = minDay;
            sellDay = j;
        }
        if (price[j] < minPrice) {
            minPrice = price[j];
            minDay = j;
        }
    }
    if (buyDay == -1) {
        cout << "No profitable trade" << endl;
    } else {
        cout << "Buy day: " << buyDay << endl;
        cout << "Sell day: " << sellDay << endl;
        cout << "Profit: " << bestProfit << endl;
    }
    return 0;
}

