// recursion shows the started line before diving and the done line after returning
void runTask(int k) {
    if (k == 0) {
        return;
    }
    cout << "Subtask " << k << " started" << endl;
    runTask(k - 1);
    cout << "Subtask " << k << " done" << endl;
}

