#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;
    int denoms[6] = {500, 100, 50, 10, 5, 1};
    long long totals[6] = {0, 0, 0, 0, 0, 0};
    int served = 0;
    int customer = 1;
    while (customer <= n) {
        long long amount;
        cin >> amount;
        if (amount == -1) {
            break;
        }
        long long remaining = amount;
        long long counts[6] = {0, 0, 0, 0, 0, 0};
        for (int d = 0; d < 6; d++) {
            counts[d] = remaining / denoms[d];
            remaining %= denoms[d];
            totals[d] += counts[d];
        }
        cout << "Customer " << customer << ": " << amount << endl;
        cout << "  500 x " << counts[0]
             << ", 100 x " << counts[1]
             << ", 50 x " << counts[2]
             << ", 10 x " << counts[3]
             << ", 5 x " << counts[4]
             << ", 1 x " << counts[5] << endl;
        served++;
        customer++;
    }
    cout << "Denomination totals:" << endl;
    for (int d = 0; d < 6; d++) {
        cout << denoms[d] << ": " << totals[d] << endl;
    }
    cout << "Customers served: " << served << endl;
    return 0;
}

#include <iostream>
#include <string>
