#include <iostream>
#include <string>
using namespace std;

int main() {
    string target;
    cin >> target;
    // lowercase the target word
    for (int i = 0; i < (int)target.length(); i++) {
        char c = target[i];
        if (c >= 'A' && c <= 'Z') {
            c = c - 'A' + 'a';
        }
        target[i] = c;
    }
    cin.ignore(); // skip the newline left after reading the word
    string line;
    getline(cin, line);

    int count = 0;
    string word = "";
    for (int i = 0; i <= (int)line.length(); i++) {
        if (i == (int)line.length() || line[i] == ' ') {
            if (word.length() > 0) {
                // lowercase the scanned word, then compare
                for (int j = 0; j < (int)word.length(); j++) {
                    char c = word[j];
                    if (c >= 'A' && c <= 'Z') {
                        c = c - 'A' + 'a';
                    }
                    word[j] = c;
                }
                if (word == target) {
                    count++;
                }
                word = "";
            }
        } else {
            word += line[i];
        }
    }
    cout << "Count: " << count << endl;
    return 0;
}

